const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>({agents:[{name:'Manager',role:'Project lead',provider:'OpenAI',initial:'M'},{name:'Gemini',role:'Researcher',provider:'Google',initial:'G'},{name:'ChatGPT',role:'Data analyst',provider:'OpenAI',initial:'C'},{name:'Claude',role:'Software engineer',provider:'Anthropic',initial:'C'},{name:'QA Agent',role:'Quality assurance',provider:'Unconfigured',initial:'Q'}],projects:[],events:[],animations:true});
let state;try{state=JSON.parse(localStorage.getItem('ai-office-v1'))}catch{}if(!state||!Array.isArray(state.agents)||!Array.isArray(state.projects))state=defaults();
// V2: upgrade saved data in place (stable ids, tasks, approvals, artifacts); older fields are kept.
if(window.RuangCore)state=RuangCore.migrate(state,defaults);
let view='Office',selected=state.projects[0]?.id;
const persist=()=>{try{localStorage.setItem('ai-office-v1',JSON.stringify(state))}catch{alert('Browser storage is unavailable. Changes will last only for this session.')}};
const project=()=>state.projects.find(p=>p.id===selected)||state.projects[0];
const log=(text,p)=>{state.events.unshift({text,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),projectId:p?.id});state.events=state.events.slice(0,100)};
const statusFor=i=>{const p=state.projects.find(p=>p.status==='Running'||p.status==='Waiting approval');if(!p)return 'Idle';if(p.status==='Waiting approval')return i===0?'Waiting approval':'Idle';return p.tasks[p.step]?.agent===i?'Working':'Idle'};
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const avatar=a=>`<div class="avatar">${esc(a.initial)}</div>`;
const navs=[['Office','⌂'],['Inbox','✉'],['Employees','♙'],['Projects','▣'],['Tasks','✓'],['Files','▤'],['Activity','≋'],['Settings','⚙']];
function render(){const p=project(),completed=state.projects.reduce((n,p)=>n+p.tasks.filter(t=>t.status==='Completed').length,0);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span>▦</span> AI OFFICE</div><div class="tagline">Same ideas. More people.</div><nav class="nav">${navs.map(([n,i])=>`<button data-view="${n}" class="${view===n?'active':''}"><span class="nav-icon">${i}</span>${n}</button>`).join('')}</nav><div class="owner"><div class="avatar">R</div><div>Razeen's office<div class="small muted">Local workspace</div></div></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">YOUR LOCAL AI WORKFORCE</div><h1>${view==='Office'?'A little office. Big ideas.':view}</h1></div><div class="top-actions">${badge('Web preview')}<button class="primary" data-action="new-project">＋ New project</button></div></header>${view==='Office'?`<section class="stats"><div class="stat"><span class="small muted">Your workforce</span><strong>${state.agents.length} <span class="small muted">employees</span></strong><span class="small muted">Ready for your next idea</span></div><div class="stat"><span class="small muted">Active projects</span><strong>${state.projects.filter(p=>p.status!=='Completed').length}</strong><span class="small muted">${state.projects.length} total projects</span></div><div class="stat"><span class="small muted">Tasks completed</span><strong>${completed}</strong><span class="small muted">Across your workspace</span></div><div class="stat"><span class="small muted">API spend</span><strong>$0.00</strong><span class="small muted">Demo · no model calls</span></div></section><div class="workspace"><section class="panel"><div class="panel-head"><h2>The office</h2><span class="small muted">Click an employee to check in</span></div><div class="office" role="group" aria-label="Interactive office"><button class="station s0" data-agent="0"><b>${esc(state.agents[0].name)}</b><span>${statusFor(0)}</span></button>${[1,2,3,4].map(i=>`<button class="station s${i}" data-agent="${i}"><b>${esc(state.agents[i].name)}</b><span>${statusFor(i)}</span></button>`).join('')}</div><div class="office-footer"><span>HUMAN IDEAS → AI EXECUTION</span><span>Office concept artwork · demo status overlays</span></div></section><aside class="rail"><section class="panel pad"><div class="row"><h2>Project board</h2>${p?badge(p.status,p.status==='Waiting approval'?'demo':''):''}</div>${p?projectSummary(p):`<div class="project-name">What shall we work on?</div><p class="small muted">Give your team a goal and try the full demo workflow.</p><button class="primary" data-action="demo">Try a demo project</button>`}</section><section class="panel pad"><h2>Team status</h2>${state.agents.map((a,i)=>`<div class="team-row" role="button" tabindex="0" data-agent="${i}">${avatar(a)}<div class="small">${esc(a.name)}</div>${badge(statusFor(i))}</div>`).join('')}</section></aside></div><section class="panel activity"><div class="panel-head"><h2>Office activity</h2><button class="quiet small" data-view="Activity">View all</button></div>${eventsHTML(4)}</section>`:bodyView(p)}</main></div>`;}
function projectSummary(p){const done=p.tasks.filter(t=>t.status==='Completed').length;return `<div class="project-name">${esc(p.name)}</div><p class="small muted">${esc(p.goal)}</p><div class="progress" aria-label="${done} of ${p.tasks.length} tasks completed"><div style="width:${done/p.tasks.length*100}%"></div></div><div class="row small muted"><span>${done} / ${p.tasks.length} tasks</span><span>Sample walkthrough, simulated</span></div><div style="margin-top:18px">${p.status==='Draft'?`<button class="primary" data-run="${p.id}">Start the walkthrough</button>`:p.status==='Waiting approval'?`<button class="primary" data-approve="${p.id}">Review approval</button>`:p.status==='Completed'?`<button data-output="${p.id}">Open report</button>`:p.status==='Paused'?`<button data-run="${p.id}">Resume demo</button>`:`<button data-pause="${p.id}">Pause run</button>`}</div>`}
function eventsHTML(limit=100){return state.events.length?state.events.slice(0,limit).map(e=>`<div class="event"><time>${esc(e.time)}</time><span class="event-dot"></span><span>${esc(e.text)}</span></div>`).join(''):'<div class="empty">Your team’s activity will appear here when a project starts.</div>'}
function bodyView(p){if(view==='Employees')return `<div class="notice">Choose each employee's model in their Employee details, and save the provider's key under Settings, AI Connections. Tasks and chat then use that model.</div><div class="grid">${state.agents.map((a,i)=>`<section class="panel card">${avatar(a)}<div class="row"><h2>${esc(a.name)}</h2>${badge(statusFor(i))}</div><p>${esc(a.role)}</p><p>Preferred provider: ${esc(a.provider)}</p><button data-agent="${i}">Manage employee</button></section>`).join('')}</div>`;if(view==='Projects')return state.projects.length?`<div class="grid">${state.projects.map(p=>`<section class="panel card">${badge(p.status)}${projectSummary(p)}<button style="margin-top:12px" class="quiet" data-select="${p.id}">View tasks</button></section>`).join('')}</div>`:'<section class="panel empty"><h2>Your next idea starts here.</h2><p>Create a project or explore the sample workflow.</p><button class="primary" data-action="demo">Try a demo project</button></section>';if(view==='Tasks')return p?`<div class="row" style="margin-bottom:18px"><h2>${esc(p.name)}</h2><select aria-label="Choose project" id="project-select" style="width:auto;max-width:50%">${state.projects.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="notice">This is the sample walkthrough: its steps are simulated to show how a project flows. Tasks you assign to employees are real.</div><section class="panel">${p.tasks.map((t,i)=>`<div class="task"><div class="avatar">${i+1}</div><div class="task-main"><h3>${esc(t.title)}</h3><p class="muted">${esc(state.agents[t.agent].name)} · ${esc(t.detail)}</p></div>${badge(t.status,t.status==='Waiting approval'?'demo':'')}</div>`).join('')}</section><section class="panel pad" style="margin-top:20px">${projectSummary(p)}</section>`:'<div class="panel empty">Create a project to give your team its first task.</div>';if(view==='Activity')return `<section class="panel">${eventsHTML()}</section>`;if(view==='Files')return `<div class="notice">This web preview keeps sample reports in this browser and cannot open your local files. Use the desktop app for real files and saved task outputs.</div><div class="stack">${state.projects.filter(p=>p.output).map(p=>`<section class="panel pad row"><div><h3>${esc(p.name)}: report.md</h3><span class="small muted">Demo report · approved output</span></div><button data-output="${p.id}">Open report</button></section>`).join('')||'<div class="panel empty">Completed project reports will appear here.</div>'}</div>`;return `<section class="panel pad"><h2>Web preview</h2><p class="muted">Projects, employees and activity are saved in this browser only. Another browser starts a separate workspace.</p><h3>Model connections</h3><p class="muted">Real chat and tasks run in the Ruang desktop app, which keeps your provider keys encrypted on your computer. Keys are never entered into a web page. The web version will need a Ruang server for this, which is not set up yet.</p><button data-action="export">Export workspace</button><button class="quiet danger" data-action="reset" style="margin-left:12px">Reset this browser's data</button></section>`}
function show(html){$('#dialog').innerHTML=html;$('#dialog').showModal()}
function newProject(){show(`<h2>Give your team a goal</h2><p class="muted small">New projects start with a sample plan whose steps are simulated, so no model is used. For real work, assign tasks to employees from the office.</p><form id="project-form"><label for="name">Project name</label><input id="name" name="name" required maxlength="80" placeholder="e.g. Research my next product"><label for="goal">What would you like to achieve?</label><textarea id="goal" name="goal" required maxlength="1000" placeholder="Describe the outcome you have in mind…"></textarea><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary">Create project</button></div></form>`)}
function createProject(name,goal){const p={id:crypto.randomUUID(),name,goal,status:'Draft',step:0,tasks:[{title:'Plan the work',agent:0,detail:'Define the scope and acceptance criteria.',status:'Ready'},{title:'Research the brief',agent:1,detail:'Prepare sample research notes.',status:'Queued'},{title:'Analyse findings',agent:2,detail:'Organise opportunities and constraints.',status:'Queued'},{title:'Draft the deliverable',agent:3,detail:'Assemble a sample implementation outline.',status:'Queued'},{title:'Review the result',agent:4,detail:'Check completeness and flag limitations.',status:'Queued'},{title:'Save the final report',agent:0,detail:'Wait for your approval before saving.',status:'Queued'}]};state.projects.unshift(p);selected=p.id;log(`Manager created a six-task plan for “${name}”.`,p);persist();render();return p}
function start(id){if(state.projects.some(x=>x.status==='Running'&&x.id!==id)){alert('Pause the current demo before starting another project.');return}const p=state.projects.find(x=>x.id===id);if(p.step===5){p.status='Waiting approval';p.tasks[5].status='Waiting approval';persist();render();return}p.status='Running';p.tasks[p.step].status='Running';p.nextAt=Date.now()+2500;log(`${state.agents[p.tasks[p.step].agent].name} started “${p.tasks[p.step].title}”.`,p);persist();render()}
function tick(){let changed=false;for(const p of state.projects){if(p.status!=='Running'||Date.now()<p.nextAt)continue;const t=p.tasks[p.step];t.status='Completed';log(`${state.agents[t.agent].name} completed “${t.title}” (demo).`,p);p.step++;if(p.step===5){p.status='Waiting approval';p.tasks[5].status='Waiting approval';log('Manager requested approval to save the demo report.',p)}else{p.tasks[p.step].status='Running';p.nextAt=Date.now()+2500}changed=true}if(changed){persist();render()}}
function approval(id){const p=state.projects.find(x=>x.id===id);show(`<h2>Review requested action</h2>${badge('Waiting for you','demo')}<p><strong>Manager</strong> wants to save the final demo report for <strong>${esc(p.name)}</strong>.</p><p class="muted">Target: this app’s workspace.<br>Effect: creates an output under Files. No external files are changed, and nothing is sent.</p><div class="dialog-actions"><button data-deny="${id}">Deny</button><button class="primary" data-confirm="${id}">Approve and save</button></div>`)}
function finish(id){const p=state.projects.find(x=>x.id===id);p.status='Completed';p.tasks[5].status='Completed';p.output=`# ${p.name}\n\nDEMO REPORT. No research or execution by a model was performed.\n\n## Your objective\n${p.goal}\n\n## Workflow demonstrated\n1. Manager created a bounded plan.\n2. Researcher completed a simulated research step.\n3. Analyst completed a simulated analysis step.\n4. Engineer completed a simulated drafting step.\n5. QA completed a simulated review step.\n6. You approved saving this report.\n\n## Next steps for real execution\nConnect model providers through a local backend, supply source documents, and implement isolated tool execution before treating outputs as completed work.\n\nAPI calls: 0\nAPI spend: $0.00\n`;log(`You approved the report. “${p.name}” is complete.`,p);persist();$('#dialog').close();render()}
function output(id){const p=state.projects.find(x=>x.id===id);show(`<h2>Project report</h2><pre>${esc(p.output)}</pre><div class="dialog-actions"><button data-close>Close</button><button class="primary" data-download="${id}">Download report</button></div>`)}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function employee(i){const a=state.agents[i];show(`<h2>${esc(a.name)}</h2>${badge(statusFor(i))}<form id="employee-form" data-index="${i}"><label for="employee-name">Name</label><input id="employee-name" name="name" value="${esc(a.name)}" required maxlength="40"><label for="role">Role</label><input id="role" name="role" value="${esc(a.role)}" required maxlength="80"><label for="provider">Model provider</label><select id="provider" name="provider">${['Anthropic','OpenAI','Google','Ollama','Unconfigured'].map(v=>`<option ${a.provider===v?'selected':''}>${v}</option>`).join('')}</select><label for="model-name">Model name</label><input id="model-name" name="model" value="${esc(a.model?.model||'')}" maxlength="100" placeholder="Leave empty for the provider default (Anthropic: claude-opus-5-5)"><label for="autonomy">Autonomy</label><select id="autonomy" name="autonomy">${[['SUPERVISED','Supervised: asks before consequential actions'],['BALANCED','Balanced: asks before important decisions'],['AUTONOMOUS','Autonomous: continues unless blocked']].map(([v,l])=>`<option value="${v}" ${(a.autonomy||'BALANCED')===v?'selected':''}>${l}</option>`).join('')}</select><p class="small muted">Changing the model keeps this employee's name, look and history. Chat uses the provider's key from Settings, AI Connections.</p><div class="dialog-actions"><button type="button" data-close>Close</button><button class="primary">Save employee</button></div></form>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-agent]');if(!b)return;const d=b.dataset;if(d.close!==undefined){$('#dialog').close();return}if(d.view){view=d.view;render()}if(d.agent!==undefined)employee(Number(d.agent));if(d.action==='new-project')newProject();if(d.action==='demo'){createProject('Your first research sprint','Explore an idea, outline an approach and review a final report.');}if(d.run)start(d.run);if(d.pause){const p=state.projects.find(p=>p.id===d.pause);p.status='Paused';p.tasks[p.step].status='Paused';log('You paused the demo run.',p);persist();render()}if(d.approve)approval(d.approve);if(d.confirm)finish(d.confirm);if(d.deny){const p=state.projects.find(p=>p.id===d.deny);p.status='Paused';p.tasks[5].status='Paused';p.step=5;log('You denied saving the report. The project is paused.',p);persist();$('#dialog').close();render()}if(d.select){selected=d.select;view='Tasks';render()}if(d.output)output(d.output);if(d.download){const p=state.projects.find(p=>p.id===d.download);download('ai-office-report.md',p.output,'text/markdown')}if(d.action==='export')download('ai-office-workspace.json',JSON.stringify(state,null,2),'application/json');if(d.action==='reset'&&confirm('Remove all demo projects, reports and employee changes from this browser?')){state=window.RuangCore?RuangCore.migrate(defaults()):defaults();selected=undefined;persist();location.reload()}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,v=new FormData(f);if(f.id==='project-form'){if(!v.get('name').trim()||!v.get('goal').trim())return;$('#dialog').close();createProject(v.get('name').trim(),v.get('goal').trim())}if(f.id==='employee-form'){const a=state.agents[Number(f.dataset.index)];a.name=v.get('name').trim()||a.name;a.role=v.get('role').trim()||a.role;a.provider=v.get('provider');a.initial=a.name[0].toUpperCase();a.model={provider:{OpenAI:'openai',Anthropic:'anthropic',Google:'google',Ollama:'local'}[a.provider]||null,model:(v.get('model')||'').trim()||null};a.autonomy=v.get('autonomy')||a.autonomy;persist();$('#dialog').close();render()}});
document.addEventListener('change',e=>{if(e.target.id==='project-select'){selected=e.target.value;render()}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-agent]')){e.preventDefault();employee(Number(e.target.dataset.agent))}});
// A resumed browser session recovers active runs without silently executing them.
for(const p of state.projects)if(p.status==='Running'){p.status='Paused';p.tasks[p.step].status='Paused'}
render();setInterval(tick,600);

